"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["46808"],{35549(e){e.exports=JSON.parse('{"id":"FIN-268","slug":"market-order","term":"Market Order","also_known_as":[],"difficulty":"Intermediate","definition":"A market order is an instruction to buy or sell a security immediately at the best price currently available.","explanation":["A market order puts speed first. When you place a market buy order, it is filled at the lowest available ask price. When you place a market sell order, it is filled at the highest available bid price.","For example, if a share has a bid of 24.98 and an ask of 25.02, a market order to buy 100 shares will usually be filled at around 25.02, costing about 2,502 plus any fees.","Market orders are almost always executed, as long as there are buyers or sellers in the market, which makes them useful when getting the trade done matters more than the exact price.","The trade-off is price uncertainty. In fast-moving or thinly traded markets, the price can change between placing the order and its execution, and large orders may be filled at several prices as they work through available sellers or buyers. This difference from the expected price is called slippage. Investors who want control over the price they pay or receive often use limit orders instead."],"note":"","total":1500,"prev":{"slug":"market-manipulation","term":"Market Manipulation"},"next":{"slug":"market-risk-premium","term":"Market Risk Premium"}}')}}]);